import { issueIceServerConfig, type IceServerResponse } from "../lib/turn-config";

/** Thin server entrypoint: TURN credentials remain generated by the shared lower-level provider. */
export function getTurnCredentials(userId: number, sessionId: string): IceServerResponse {
  return issueIceServerConfig(userId, sessionId, undefined, "webrtc");
}

export function getRtcIceServers(userId: number, sessionId: string): IceServerResponse {
  return issueIceServerConfig(userId, sessionId);
}